// Helper to safely get node data without crashing if name has 01 prefix
function getNodeJson(nameOptions) {
  for (const name of nameOptions) {
    try {
      const node = $(name).first().json;
      if (node) return node;
    } catch (e) { /* try next name */ }
  }
  return {};
}

// STEP 1: Get incoming data - try multiple name variants to avoid "Referenced node doesn't exist"
const body = $input.first().json?.body || $input.first().json || {};

// STEP 2: Get validation - try with and without 01 prefix
const validation = getNodeJson([
  '01 Validation-CorrelationID',
  'Validation-CorrelationID',
  'Validation Correlation ID',
  '01 Validation'
]);

// STEP 3: Get retrieval context - Build Retrieval Context node
const retrieval = getNodeJson([
  'Build Retrieval Context',
  'Build Retrieval',
  '08 Build Retrieval Context'
]);

// STEP 4: Get Gemini output - Generate Grounded Answer node
const geminiOutput = getNodeJson([
  'Generate Grounded Answer',
  'Grounded Generation',
  'Generate Grounded',
  '09 Generate Grounded Answer'
]);

// STEP 5: Correlation ID for tracing
const correlation_id = body.correlation_id || validation.correlation_id || $execution.id;

// STEP 6: Latency
const latency_ms = Date.now() - (validation.start_time || Date.now());

// STEP 7: Final project - fix General bug
const explicitProject = body.filter?.project || body.project;
const autoDetectedProject = retrieval.auto_project || validation.detected_project;
const foundInDocs = retrieval.sources?.[0]?.source;
const finalProject = explicitProject || autoDetectedProject || foundInDocs || "dubai dld fees 2026";

// STEP 8: Extract answer with rate limit handling
let answer = "I could not find this information in the uploaded documents.";
let isError = false;

if (geminiOutput.error ||!geminiOutput.candidates) {
  const lang = retrieval.language || body.language || validation.language_hint || "en";
  if (lang === "ar" || lang.startsWith("ar")) {
    answer = "عذراً، النظام مشغول حالياً. حاول بعد 20 ثانية. [source: Dubai DLD Fees 2026, page: 1]";
  } else {
    answer = "System busy, retry after 20 seconds. [source: Dubai DLD Fees 2026, page: 1]";
  }
  isError = true;
} else {
  answer = geminiOutput.candidates[0]?.content?.parts?.[0]?.text || geminiOutput.answer || answer;
}

// STEP 9: Token usage for cost
const promptTokens = geminiOutput.usageMetadata?.promptTokenCount || 0;
const completionTokens = geminiOutput.usageMetadata?.candidatesTokenCount || 0;
const totalTokens = geminiOutput.usageMetadata?.totalTokenCount || 0;

// STEP 10: Final response - Day 7 receives this
return [{
  json: {
    success:!isError,
    request_id: correlation_id,
    question: retrieval.question || body.question || "",
    answer: answer,
    sources: retrieval.sources || [{source: 'Dubai DLD Fees 2026', page: 1}],
    language: retrieval.language || validation.language_hint || "en",
    project: finalProject,
    latency_ms: latency_ms,
    timestamp: new Date().toISOString(),
    usage: { prompt_tokens: promptTokens, completion_tokens: completionTokens, total_tokens: totalTokens }
  }
}];

// Validate Query Embedding - FIXED for $input chaining
const input = $input.first().json;
// Embedding could be in different fields depending on node
const embedding = input.embedding || input.data?.[0]?.embedding || input.values || [];

return [{
  json: {
    question: input.question || $('Detect Question Language').first?.json?.question || '',
    query_embedding: embedding,
    language: input.language,
    detected_via: input.detected_via,
    correlation_id: input.correlation_id,
    start_time: input.start_time,
    user_id: input.user_id,
    session_id: input.session_id,
    channel: input.channel,
    filter: {
      ... (input.filter || {}),
      language: input.language // Auto-inject detected language for match_documents
    }
  }
}];

// Build Retrieval Context - FIXED for Day 6 Modules 2,3,6,9
const items = $input.all();
// Deduplicate by content hash (Retrieve returns same chunk 3x due to filter {})
const seen = new Set();
const docs = items.map(i => i.json).filter(j => {
  if (!j.content) return false;
  const key = j.content.slice(0,100);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

if (docs.length === 0) throw new Error('No docs from Retrieve - check Retrieve node');

// Get upstream nodes
const langNode = $('Detect Question Language').first()?.json || {};
const validationNode = $('01-Validation+CorrelationID').first()?.json || {};
const projectNode = $('Detect Project - AR/EN Bayview/Damac').first()?.json || {};

// Build context string for Gemini (grounded)
const context = docs.map(d => 
  `[Source: ${d.source || d.metadata?.source || 'Dubai DLD Fees 2026'} | Page: ${d.page || 1}]: ${d.content}`
).join('\n\n');

// Build sources array with citations
const sources = docs.map(d => ({
  source: d.source || d.metadata?.source || 'Dubai DLD Fees 2026',
  page: d.page || d.metadata?.page || 1,
  project: d.project || d.metadata?.project || 'Dubai DLD Fees 2026',
  similarity: d.similarity || d.score || 0
}));

// Get question and language properly
const finalQuestion = langNode.question || projectNode.question || validationNode.question || 'What is DLD transfer fee?';
const finalLanguage = langNode.language || 'en'; // FIX: was missing, caused 'auto'
const finalProject = projectNode.project || projectNode.requested_project || validationNode.project || 'Dubai DLD Fees 2026';

return [{ json: {
  retrieval_context: context, // For Gemini
  question: finalQuestion,
  language: finalLanguage, // FIX: Now passes 'en' not 'auto'
  project: finalProject,
  requested_project: finalProject,
  sources: sources, // FIX: Now returns objects with page/project
  correlation_id: langNode.correlation_id || validationNode.correlation_id,
  start_time: langNode.start_time || validationNode.start_time, // For latency calc
  filter: validationNode.original_body?.filter || {}
}}];

// Module 1: Fail-fast validation - skip language detection if validation failed

if ($input.first().json._isValidationError) {
  return [$input.first()];
}

// Detect Question Language v2 - FIXED - use $input, no node name ref
const input = $input.first().json;
const q = input.question || '';

let lang = 'en';
let via = 'default_en';

if (/[\u0600-\u06FF]/.test(q)) {
  if (/ہے|کیا|کہاں|کتنے|قیمت/.test(q)) {
    lang = 'ur';
    via = 'urdu_keyword';
  } else {
    lang = 'ar';
    via = 'arabic_regex';
  }
} else if (/[\u0900-\u097F]/.test(q)) {
  lang = 'hi';
  via = 'hindi_regex';
}

return [{ 
json: { 
  question: q, language: lang, detected_via: via, correlation_id: input.correlation_id, start_time: input.start_time, filter: input.filter } 
}];

// Detect Project - Dynamic filter for all docs in image_523fe6.png
const q = ($input.first().json.question || '').toLowerCase();
let filter = [];

if (q.includes('bayview')) filter.push({ source: 'Bayview Payment Plan' });
if (q.includes('damac')) filter.push({ source: 'Damac Hills 2 - Payment Plan' });
if (q.includes('community') || q.includes('e-scooter') || q.includes('off-road') || q.includes('scooter') || q.includes('club car')) {
  filter.push({ source: 'Dubai Community Rules and Regulations' });
}
if (q.includes('dld') || q.includes('fees') || q.includes('transfer')) {
  filter.push({ source: 'Dubai DLD Fees 2026' });
}

// If no specific source detected, search ALL docs (empty filter = diverse answers for portfolio)
if (filter.length === 0) filter = [];

return [{ json: { question: $input.first().json.question, filter, project: filter[0]?.source || 'general', language: $input.first().json.language || 'en' } }];

// Module 1: Request Validation + Correlation ID + Timer Start
const body = $input.first().json.body || $input.first().json || {};
const query = body.question || body.query || '';
const project = (body.project || '').toLowerCase();
const developer = (body.developer || '').toLowerCase();

// 1. Correlation ID
const correlation_id = 'req_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8);
const start_time = Date.now();

// 2. Validation
const errors = [];
if (!query || typeof query !== 'string' || query.trim() === '') {
  errors.push('Missing or empty question');
}
if (query && query.length < 3) {
  errors.push('Question too short (min 3 chars)');
}
if (query && query.length > 1000) {
  errors.push('Question too long (max 1000 chars)');
}

const allowedProjects = ['bayview', 'damac', 'dubai dld fees 2026', 'dld', 'general', ''];
if (project && !allowedProjects.some(p => project.includes(p))) {
  // Don't hard fail, just warn - allow general
  // errors.push('Invalid project');
}

if (errors.length > 0) {
  // Fail fast - return structured error that Format API Response can use
  return [{
    json: {
      success: false,
      correlation_id,
      error: errors.join('; '),
      retry: false,
      status: 400,
      start_time,
      question: query,
      project: project || 'general',
      developer: developer || 'dubai',
      _isValidationError: true
    }
  }];
}

// 3. Valid - pass forward
return [{
  json: {
    success: true,
    correlation_id,
    start_time,
    question: query.trim(),
    project: project || 'dubai dld fees 2026', // default to your DLD doc
    developer: developer || 'dubai land department',
    language_hint: body.language || 'auto',
    // keep original body for downstream
    original_body: body
  }
}];
